const pricesByTenant = new Map();

export function readPrice(tenantId, productId) {
  return pricesByTenant.get(tenantId)?.get(productId);
}

export function writePrice(tenantId, productId, price) {
  let prices = pricesByTenant.get(tenantId);
  if (prices === undefined) {
    prices = new Map();
    pricesByTenant.set(tenantId, prices);
  }
  prices.set(productId, price);
}

export function resetPrices() {
  pricesByTenant.clear();
}

