import assert from 'node:assert/strict';
import { createHmac } from 'node:crypto';
import test from 'node:test';
import { receiveWebhook } from '../src/route.mjs';

test('verifies exact bytes for semantically identical JSON encodings', () => {
  const secret = 'test-secret';
  const compact = Buffer.from('{"id":7,"status":"paid"}');
  const reformatted = Buffer.from('{\n  "status": "paid",\n  "id": 7\n}\n');
  const expectedBody = { id: 7, status: 'paid' };

  assert.notDeepEqual(compact, reformatted);
  assert.deepEqual(
    JSON.parse(compact.toString('utf8')),
    JSON.parse(reformatted.toString('utf8')),
  );

  for (const rawBody of [compact, reformatted]) {
    const signature = createHmac('sha256', secret).update(rawBody).digest('hex');
    let received;

    assert.doesNotThrow(() => {
      received = receiveWebhook(rawBody, signature, secret);
    });
    assert.deepEqual(received, expectedBody);
  }
});

