import { createHmac } from 'node:crypto';
import test from 'node:test';
import { receiveWebhook } from '../src/route.mjs';

const secret = 'test-secret';

function receiveSigned(rawBody) {
  const signature = createHmac('sha256', secret).update(rawBody).digest('hex');
  return receiveWebhook(rawBody, signature, secret);
}

test('accepts an exact provider body containing harmless whitespace', () => {
  const compact = Buffer.from('{"1":"one","2":"two"}');
  const spaced = Buffer.from('{ "1": "one", "2": "two" }');

  assert.notEqual(spaced.toString(), compact.toString());
  assert.deepEqual(JSON.parse(spaced.toString()), JSON.parse(compact.toString()));
  assert.deepEqual(receiveSigned(spaced), { 1: 'one', 2: 'two' });
});

test('accepts an exact provider body with a different property order', () => {
  const ordered = Buffer.from('{"1":"one","2":"two"}');
  const reordered = Buffer.from('{"2":"two","1":"one"}');

  assert.notEqual(reordered.toString(), ordered.toString());
  assert.deepEqual(JSON.parse(reordered.toString()), JSON.parse(ordered.toString()));
  assert.deepEqual(receiveSigned(reordered), { 1: 'one', 2: 'two' });
});

